import numpy as np
rows_=None
feats={}
def make(b_,i,j):
    c=b_
    cnt=sum(v!=0 for r in c for v in r)
    rc=sum(c[i][j+k]!=0 for k in range(6))
    cc=sum(c[k][j]!=0 for k in range(3))
    # component size of this cell's color in this band
    seen=set(); comp=0
    st=[(i,j)]; seen.add((i,j))
    while st:
        y,x=st.pop(); comp+=1
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
